//! The math kernels against Spark 4.2 on seeded random inputs
//! (`tests/fixtures/spark-4.2.0/math-differential.json`, generated by
//! `tests/scripts/gen_math_goldens.py` with ANSI off): the `double`
//! functions, `round`/`bround`/`ceil`/`floor` on every numeric type, `pmod`
//! and `greatest`/`least`. Result types are checked with the values.
//!
//! The `double` functions are compared bit for bit except where the JVM's
//! intrinsics differ from every pure-Rust implementation in the last bit
//! (see `krishiv_kernels::math`); those functions may differ in at most the
//! listed share of inputs, and by at most one ulp.
#![forbid(unsafe_code)]

use std::sync::Arc;

use arrow_array::cast::AsArray;
use arrow_array::types::{
    Decimal128Type, Float32Type, Float64Type, Int8Type, Int16Type, Int32Type, Int64Type,
};
use arrow_array::{
    Array, ArrayRef, Decimal128Array, Float32Array, Float64Array, Int8Array, Int16Array,
    Int32Array, Int64Array,
};
use arrow_schema::DataType;
use krishiv_kernels::cast::{CastMode, CastOptions, FixedOffset, cast};
use krishiv_kernels::math::{
    BinaryFn, DecimalRounding, RoundMode, UnaryFn, binary, ceil_floor_to_long, round_decimal,
    round_f32, round_f64, round_integral, unary,
};
use krishiv_kernels::{KernelCtx, KernelError, Operand, OverflowMode, SparkVersion};
use serde_json::{Value, json};

type E = Box<dyn std::error::Error>;
type R = Result<(), E>;

fn float(v: &Value) -> Option<f64> {
    match v {
        Value::Null => None,
        Value::String(s) => Some(match s.as_str() {
            "nan" => f64::NAN,
            "inf" => f64::INFINITY,
            _ => f64::NEG_INFINITY,
        }),
        v => v.as_f64(),
    }
}

fn unscaled(v: &Value) -> Option<i128> {
    v.as_str().and_then(|s| s.parse().ok())
}

/// `decimal(p,s)` as `(p, s)`.
fn decimal_type(ty: &str) -> Option<(u8, i8)> {
    let inner = ty.strip_prefix("decimal(")?.strip_suffix(')')?;
    let (p, s) = inner.split_once(',')?;
    Some((p.parse().ok()?, s.parse().ok()?))
}

#[expect(
    clippy::cast_possible_truncation,
    reason = "a float column rounds the recorded double to f32, as Spark's Python bridge does"
)]
fn column(ty: &str, values: &[Value]) -> Result<ArrayRef, E> {
    let ints: Vec<Option<i64>> = values.iter().map(Value::as_i64).collect();
    Ok(match ty {
        "tinyint" => Arc::new(Int8Array::from_iter(
            ints.iter().map(|v| v.and_then(|v| i8::try_from(v).ok())),
        )),
        "smallint" => Arc::new(Int16Array::from_iter(
            ints.iter().map(|v| v.and_then(|v| i16::try_from(v).ok())),
        )),
        "int" => Arc::new(Int32Array::from_iter(
            ints.iter().map(|v| v.and_then(|v| i32::try_from(v).ok())),
        )),
        "bigint" => Arc::new(Int64Array::from(ints)),
        "float" => Arc::new(Float32Array::from_iter(
            values.iter().map(|v| float(v).map(|f| f as f32)),
        )),
        "double" => Arc::new(Float64Array::from_iter(values.iter().map(float))),
        other => {
            let (p, s) = decimal_type(other).ok_or_else(|| format!("type {other}"))?;
            Arc::new(
                Decimal128Array::from_iter(values.iter().map(unscaled))
                    .with_precision_and_scale(p, s)?,
            )
        }
    })
}

/// Spark's type name of an Arrow type.
fn spark_type(t: &DataType) -> String {
    match t {
        DataType::Int8 => "tinyint".into(),
        DataType::Int16 => "smallint".into(),
        DataType::Int32 => "int".into(),
        DataType::Int64 => "bigint".into(),
        DataType::Float32 => "float".into(),
        DataType::Float64 => "double".into(),
        DataType::Decimal128(p, s) => format!("decimal({p},{s})"),
        other => other.to_string(),
    }
}

/// A comparable rendering of row `i`: floats as canonical bits.
fn render(a: &dyn Array, i: usize) -> Value {
    if a.is_null(i) {
        return Value::Null;
    }
    match a.data_type() {
        DataType::Float64 => {
            let v = a.as_primitive::<Float64Type>().value(i);
            json!(
                if v.is_nan() {
                    0x7ff8_0000_0000_0000
                } else {
                    v.to_bits()
                }
                .to_string()
            )
        }
        DataType::Float32 => {
            let v = a.as_primitive::<Float32Type>().value(i);
            json!(if v.is_nan() { 0x7fc0_0000 } else { v.to_bits() }.to_string())
        }
        DataType::Int8 => json!(a.as_primitive::<Int8Type>().value(i)),
        DataType::Int16 => json!(a.as_primitive::<Int16Type>().value(i)),
        DataType::Int32 => json!(a.as_primitive::<Int32Type>().value(i)),
        DataType::Int64 => json!(a.as_primitive::<Int64Type>().value(i)),
        DataType::Decimal128(..) => json!(a.as_primitive::<Decimal128Type>().value(i).to_string()),
        other => json!(format!("unrendered {other}")),
    }
}

/// The same rendering of a recorded result.
fn expected(out_type: &str, v: &Value) -> Value {
    if v.is_null() || v.get("error").is_some() {
        return v.clone();
    }
    match out_type {
        "double" => {
            let f = float(v).unwrap_or(f64::NAN);
            json!(
                if f.is_nan() {
                    0x7ff8_0000_0000_0000
                } else {
                    f.to_bits()
                }
                .to_string()
            )
        }
        "float" => {
            let f = float(v).unwrap_or(f64::NAN);
            #[expect(
                clippy::cast_possible_truncation,
                reason = "the recorded double is a float"
            )]
            let f = f as f32;
            json!(if f.is_nan() { 0x7fc0_0000 } else { f.to_bits() }.to_string())
        }
        _ => v.clone(),
    }
}

const UNARY: &[(&str, UnaryFn)] = &[
    ("sqrt", UnaryFn::Sqrt),
    ("cbrt", UnaryFn::Cbrt),
    ("exp", UnaryFn::Exp),
    ("expm1", UnaryFn::Expm1),
    ("ln", UnaryFn::Ln),
    ("log10", UnaryFn::Log10),
    ("log2", UnaryFn::Log2),
    ("log1p", UnaryFn::Log1p),
    ("sin", UnaryFn::Sin),
    ("cos", UnaryFn::Cos),
    ("tan", UnaryFn::Tan),
    ("asin", UnaryFn::Asin),
    ("acos", UnaryFn::Acos),
    ("atan", UnaryFn::Atan),
    ("sinh", UnaryFn::Sinh),
    ("cosh", UnaryFn::Cosh),
    ("tanh", UnaryFn::Tanh),
    ("asinh", UnaryFn::Asinh),
    ("acosh", UnaryFn::Acosh),
    ("atanh", UnaryFn::Atanh),
    ("cot", UnaryFn::Cot),
    ("csc", UnaryFn::Csc),
    ("sec", UnaryFn::Sec),
    ("degrees", UnaryFn::Degrees),
    ("radians", UnaryFn::Radians),
    ("rint", UnaryFn::Rint),
    ("signum", UnaryFn::Signum),
];

const BINARY: &[(&str, BinaryFn)] = &[
    ("pow", BinaryFn::Pow),
    ("atan2", BinaryFn::Atan2),
    ("hypot", BinaryFn::Hypot),
    ("log", BinaryFn::Log),
];

/// Functions whose results may differ from the JVM's in the last bit, with
/// the share of random inputs (per mille) allowed to.
const ULP_TOLERANCE: &[(&str, usize)] = &[
    ("ln", 40),
    ("sin", 30),
    ("cos", 30),
    ("tan", 30),
    ("atan2", 40),
    ("log10", 20),
    // `1 / tan`, `1 / sin`, `1 / cos` and `ln(x) / ln(base)` inherit them.
    ("cot", 60),
    ("csc", 30),
    ("sec", 30),
    ("log", 30),
    // Spark 4.0 and 4.1: `log(x + sqrt(x*x + 1))` on the JVM's `log`.
    ("asinh", 30),
];

/// The largest distance in ulps a tolerated function may be off.
fn max_ulps(func: &str) -> u64 {
    if matches!(func, "log10" | "cot" | "csc" | "sec") {
        2
    } else {
        1
    }
}

/// `(function name, arguments after the first column)` of a group's SQL.
fn call_of(sql: &str) -> Result<(&str, Vec<i32>), E> {
    let (name, rest) = sql.split_once('(').ok_or("sql")?;
    let args = rest.trim_end_matches(')');
    let extra = args
        .split(',')
        .skip(1)
        .filter_map(|a| a.trim().parse().ok())
        .collect();
    Ok((name, extra))
}

fn kernel(name: &str, extra: &[i32], cols: &[ArrayRef], ctx: &KernelCtx) -> Result<ArrayRef, E> {
    let ansi_off = OverflowMode::JavaWrap;
    if let Some((_, f)) = UNARY.iter().find(|(n, _)| *n == name) {
        return Ok(Arc::new(unary(
            *f,
            cols[0].as_primitive::<Float64Type>(),
            ctx,
        )));
    }
    if let Some((_, f)) = BINARY.iter().find(|(n, _)| *n == name) {
        let (l, r) = (
            cols[0].as_primitive::<Float64Type>(),
            cols[1].as_primitive::<Float64Type>(),
        );
        return Ok(Arc::new(binary(*f, Operand::Array(l), Operand::Array(r))?));
    }
    let scale = extra.first().copied();
    let c0 = &cols[0];
    match name {
        "round" | "bround" => {
            let mode = if name == "round" {
                RoundMode::HalfUp
            } else {
                RoundMode::HalfEven
            };
            let scale = scale.unwrap_or(0);
            macro_rules! int {
                ($t:ty) => {
                    Arc::new(round_integral(
                        c0.as_primitive::<$t>(),
                        scale,
                        mode,
                        ansi_off,
                    )?)
                };
            }
            Ok(match c0.data_type() {
                DataType::Int8 => int!(Int8Type),
                DataType::Int16 => int!(Int16Type),
                DataType::Int32 => int!(Int32Type),
                DataType::Int64 => int!(Int64Type),
                DataType::Float64 => {
                    Arc::new(round_f64(c0.as_primitive::<Float64Type>(), scale, mode))
                }
                DataType::Float32 => {
                    Arc::new(round_f32(c0.as_primitive::<Float32Type>(), scale, mode))
                }
                _ => Arc::new(round_decimal(
                    c0.as_primitive::<Decimal128Type>(),
                    scale,
                    mode.into(),
                )?),
            })
        }
        "ceil" | "floor" => {
            let ceil = name == "ceil";
            let rounding = if ceil {
                DecimalRounding::Ceiling
            } else {
                DecimalRounding::Floor
            };
            let opts = CastOptions {
                mode: CastMode::Ansi,
                time_zone: &FixedOffset(0),
            };
            let decimal_of = |a: &ArrayRef| -> Result<Decimal128Array, E> {
                let to = match a.data_type() {
                    DataType::Int8 => DataType::Decimal128(3, 0),
                    DataType::Int16 => DataType::Decimal128(5, 0),
                    DataType::Int32 => DataType::Decimal128(10, 0),
                    DataType::Int64 => DataType::Decimal128(20, 0),
                    DataType::Float32 => DataType::Decimal128(14, 7),
                    DataType::Float64 => DataType::Decimal128(30, 15),
                    _ => return Ok(a.as_primitive::<Decimal128Type>().clone()),
                };
                Ok(cast(a, &to, &opts)?
                    .as_primitive::<Decimal128Type>()
                    .clone())
            };
            match (c0.data_type(), scale) {
                (DataType::Float64, None) => Ok(Arc::new(ceil_floor_to_long(
                    c0.as_primitive::<Float64Type>(),
                    ceil,
                ))),
                (DataType::Float32, None) => {
                    let wide = cast(c0, &DataType::Float64, &opts)?;
                    Ok(Arc::new(ceil_floor_to_long(
                        wide.as_primitive::<Float64Type>(),
                        ceil,
                    )))
                }
                (DataType::Int8 | DataType::Int16 | DataType::Int32 | DataType::Int64, None) => {
                    Ok(cast(c0, &DataType::Int64, &opts)?)
                }
                (_, scale) => {
                    let d = decimal_of(c0)?;
                    Ok(Arc::new(round_decimal(&d, scale.unwrap_or(0), rounding)?))
                }
            }
        }
        other => Err(format!("function {other}").into()),
    }
}

/// Checks the recorded groups of `spark-<version>/math-differential.json`
/// against the kernels of that Spark version; `min_rows` guards a truncated
/// fixture.
fn check(version: &str, spark: SparkVersion, min_rows: usize) -> R {
    let ctx = KernelCtx::new().with_spark_version(spark);
    let path = krishiv_testkit::tests_dir()
        .join(format!("fixtures/spark-{version}/math-differential.json"));
    let fx: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
    let mut failures = Vec::new();
    let mut checked = 0;
    let mut diffs: std::collections::BTreeMap<String, usize> = Default::default();
    let mut totals: std::collections::BTreeMap<String, usize> = Default::default();
    for g in fx["groups"].as_array().ok_or("groups")? {
        let name = g["name"].as_str().unwrap_or_default();
        let sql = g["sql"].as_str().unwrap_or_default();
        let out_type = g["out_type"].as_str().unwrap_or_default();
        let rows = g["rows"].as_array().ok_or("rows")?;
        let types = g["types"].as_array().ok_or("types")?;
        if matches!(name, "sign_int" | "sign_decimal") {
            continue;
        }
        let cols: Vec<ArrayRef> = types
            .iter()
            .enumerate()
            .map(|(i, t)| {
                column(
                    t.as_str().unwrap_or_default(),
                    &rows.iter().map(|r| r[i].clone()).collect::<Vec<_>>(),
                )
            })
            .collect::<Result<_, _>>()?;
        let (func, extra) = call_of(sql)?;
        let want: Vec<Value> = g["out"]
            .as_array()
            .ok_or("out")?
            .iter()
            .map(|v| expected(out_type, v))
            .collect();
        let got: Vec<Value> = match kernel(func, &extra, &cols, &ctx) {
            Ok(a) => {
                if spark_type(a.data_type()) != out_type {
                    failures.push(format!(
                        "{name}: type {} vs Spark {out_type}",
                        spark_type(a.data_type())
                    ));
                    continue;
                }
                (0..a.len()).map(|i| render(a.as_ref(), i)).collect()
            }
            Err(_) => {
                // A row-level error: run the rows one by one.
                (0..rows.len())
                    .map(|i| {
                        let one: Vec<ArrayRef> = cols.iter().map(|c| c.slice(i, 1)).collect();
                        match kernel(func, &extra, &one, &ctx) {
                            Ok(a) => render(a.as_ref(), 0),
                            Err(e) => json!({"error": e.downcast_ref::<KernelError>().map_or("other", |k| k.error_class().name())}),
                        }
                    })
                    .collect()
            }
        };
        for (i, (g_, w)) in got.iter().zip(&want).enumerate() {
            checked += 1;
            if g_ != w {
                let tolerated = ULP_TOLERANCE.iter().any(|(n, _)| *n == func);
                if tolerated {
                    *diffs.entry(func.to_owned()).or_default() += 1;
                    if !within_ulps(g_, w, max_ulps(func)) {
                        failures.push(format!(
                            "{name} row {i}: too far: {g_} vs Spark {w}: {}",
                            rows[i]
                        ));
                    }
                } else if failures.len() < 40 {
                    failures.push(format!("{name} row {i} {}: {g_} vs Spark {w}", rows[i]));
                }
            }
        }
        if ULP_TOLERANCE.iter().any(|(n, _)| *n == func) {
            *totals.entry(func.to_owned()).or_default() += rows.len();
        }
    }
    for (f, bad) in &diffs {
        let total = totals.get(f).copied().unwrap_or(1);
        let limit = ULP_TOLERANCE
            .iter()
            .find(|(n, _)| n == f)
            .map_or(0, |(_, m)| *m);
        if bad * 1000 > total * limit {
            failures.push(format!(
                "{f}: {bad} of {total} inputs differ from Spark, more than {limit} per mille"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    assert!(checked >= min_rows, "only {checked} rows");
    Ok(())
}

#[test]
fn math_kernels_match_spark_4_2() -> R {
    check("4.2.0", SparkVersion::V4_2, 30_000)
}

/// Spark 4.0 and 4.1 (JDK 17) differ from 4.2 (JDK 21) in `asinh` and `acosh`
/// only; their fixtures hold just those groups.
#[test]
fn math_kernels_match_spark_4_1() -> R {
    check("4.1.0", SparkVersion::V4_1, 500)
}

#[test]
fn math_kernels_match_spark_4_0() -> R {
    check("4.0.0", SparkVersion::V4_0, 500)
}

fn within_ulps(got: &Value, want: &Value, ulps: u64) -> bool {
    let (Some(g), Some(w)) = (
        got.as_str().and_then(|s| s.parse::<u64>().ok()),
        want.as_str().and_then(|s| s.parse::<u64>().ok()),
    ) else {
        return got == want;
    };
    g.abs_diff(w) <= ulps
}
